#include <iostream>using namespace std;int main() {	setlocale(0, "rus");	int i;	while (true) {		cout << "Введите целое число: ";		cin >> i;		if (cin.good()) { //если нет ошибок			break;		} //выйти из цикла		cin.clear();//Очистить биты ошибок		cout << "Неправильный ввод данных\n";		cin.ignore(10, '\n'); //удалить из потока 10 символов до знака перехода на новую строку	}	cout << "целое число: " << i;	return 0;}